# =====================================================================
# Task targets — SINGLE SOURCE OF TRUTH for the "move one piece" episode.
#
# On every reset the ACTIVE_PIECE is placed on SOURCE_SQUARE, and that same
# SOURCE_SQUARE is painted RED (the piece to move). TARGET_SQUARE is painted
# GREEN (the destination). Because the placement event and the red-coloring
# event both reference SOURCE_SQUARE below, the red square can never drift out
# of sync with where the piece actually sits.
#
# These are hardcoded for now. To generate synthetic data, these are the values
# to drive with Sobol sampling (and, per-episode, ACTIVE_PIECE can be varied
# across the scene's pieces for domain randomization).
#
# Squares are (row, column) with 0 <= row, column <= 7.
# =====================================================================
ACTIVE_PIECE = "bishop_white"
SOURCE_SQUARE = (2, 2)  # RED  — where the piece to move currently sits
TARGET_SQUARE = (3, 3)  # GREEN — destination square (placeholder)

