# Keep the top-left square fixed in the robot's view while making the board
# smaller.  Square_0_0 is the far-left corner when viewed from the robot at
# +X, and the remaining squares extend from it toward the robot and to the
# right.  Re-spacing from this anchor therefore makes the near edge recede.
CHESSBOARD_SQUARE_SIZE = 0.0333
CHESSBOARD_ANCHOR_SQUARE = (0, 0)
CHESSBOARD_BORDER_SIZE = 0.30
# Intentionally unchanged: mass tuning (remedy 6) is out of scope for now.
PIECE_MASS_KG = 0.02

# Free pieces need only a small solver budget while resting on the board. The
