def _set_canonical_cube_extent(prim) -> None:
    """Make a Cube's authored extent agree with its local size.

    The source board authored an already-scaled Z extent and then scaled that
    extent a second time in USD.  PhysX uses the Cube size while BBox queries
    use the stale extent, which made resets target a point inside the board.
    """
    cube = UsdGeom.Cube(prim)
    size = cube.GetSizeAttr().Get()
    if size is None:
        size = 2.0
    half_size = 0.5 * float(size)
    cube.CreateExtentAttr().Set(
        [
            Gf.Vec3f(-half_size, -half_size, -half_size),
            Gf.Vec3f(half_size, half_size, half_size),
        ]
    )


def _resize_chessboard(scene_prim) -> None:
    """Resize the visuals and replace 65 tiled colliders with one surface."""
    stage = scene_prim.GetStage()
    board_path = scene_prim.GetPath().AppendChild("ChessBoard")
    anchor_row, anchor_col = CHESSBOARD_ANCHOR_SQUARE

    def _translation(row: int, col: int):
        square_path = board_path.AppendChild(f"Square_{row}_{col}")
        square = stage.GetPrimAtPath(square_path)
        if not square.IsValid():
            raise RuntimeError(f"Chessboard square does not exist: {square_path}")
        value = square.GetAttribute("xformOp:translate").Get()
        if value is None:
            raise RuntimeError(f"Chessboard square has no translation: {square_path}")
        return value

    anchor_position = _translation(anchor_row, anchor_col)
    row_step = _translation(anchor_row + 1, anchor_col) - anchor_position
    col_step = _translation(anchor_row, anchor_col + 1) - anchor_position
    if row_step.GetLength() == 0.0 or col_step.GetLength() == 0.0:
        raise RuntimeError("Chessboard row/column spacing must be non-zero.")
    row_direction = row_step / row_step.GetLength()
    col_direction = col_step / col_step.GetLength()

    # Center the yellow BasePlate so its margin is equal on all four sides.
    board_center = (
        anchor_position
        + row_direction * (3.5 * CHESSBOARD_SQUARE_SIZE)
        + col_direction * (3.5 * CHESSBOARD_SQUARE_SIZE)
    )
    base_plate_path = board_path.AppendChild("BasePlate")
    base_plate = stage.GetPrimAtPath(base_plate_path)
    base_plate_translate = base_plate.GetAttribute("xformOp:translate")
    base_plate_scale = base_plate.GetAttribute("xformOp:scale")
    base_plate_position = base_plate_translate.Get()
    base_plate_size = base_plate_scale.Get()
    if base_plate_position is None:
        raise RuntimeError(f"Chessboard base plate has no translation: {base_plate_path}")
    if base_plate_size is None:
        raise RuntimeError(f"Chessboard base plate has no scale: {base_plate_path}")
    base_plate_translate.Set(Gf.Vec3d(board_center[0], board_center[1], base_plate_position[2]))
    base_plate_scale.Set(Gf.Vec3d(CHESSBOARD_BORDER_SIZE, CHESSBOARD_BORDER_SIZE, base_plate_size[2]))
    _set_canonical_cube_extent(base_plate)
    if base_plate.HasAPI(UsdPhysics.CollisionAPI):
        UsdPhysics.CollisionAPI(base_plate).GetCollisionEnabledAttr().Set(False)
    if base_plate.HasAPI(UsdPhysics.RigidBodyAPI):
        UsdPhysics.RigidBodyAPI(base_plate).GetRigidBodyEnabledAttr().Set(False)

    square_thickness = None
    square_center_z = None

    for row in range(8):
        for col in range(8):
            square_path = board_path.AppendChild(f"Square_{row}_{col}")
            square = stage.GetPrimAtPath(square_path)
            translate_attr = square.GetAttribute("xformOp:translate")
            scale_attr = square.GetAttribute("xformOp:scale")
            scale = scale_attr.Get()
            if scale is None:
                raise RuntimeError(f"Chessboard square has no scale: {square_path}")

            position = (
                anchor_position
                + row_direction * ((row - anchor_row) * CHESSBOARD_SQUARE_SIZE)
                + col_direction * ((col - anchor_col) * CHESSBOARD_SQUARE_SIZE)
            )
            translate_attr.Set(position)
            scale_attr.Set(Gf.Vec3d(CHESSBOARD_SQUARE_SIZE, CHESSBOARD_SQUARE_SIZE, scale[2]))
            _set_canonical_cube_extent(square)
            if square.HasAPI(UsdPhysics.CollisionAPI):
                UsdPhysics.CollisionAPI(square).GetCollisionEnabledAttr().Set(False)
            if square.HasAPI(UsdPhysics.RigidBodyAPI):
                UsdPhysics.RigidBodyAPI(square).GetRigidBodyEnabledAttr().Set(False)
            if square_thickness is None:
                square_thickness = abs(float(scale[2]))
                square_center_z = float(position[2])

    if square_thickness is None or square_center_z is None:
        raise RuntimeError("Chessboard contains no squares from which to build its surface collider.")

    # A single primitive eliminates all internal edges between the 64 visual
    # squares.  It is invisible but remains the only physical board surface.
    surface_path = board_path.AppendChild(mdp.BOARD_SURFACE_COLLIDER_NAME)
    surface = UsdGeom.Cube.Define(stage, surface_path)
    surface.CreateSizeAttr(1.0)
    _set_canonical_cube_extent(surface.GetPrim())
    surface_xform = UsdGeom.Xformable(surface)
    surface_xform.AddTranslateOp().Set(
        Gf.Vec3d(float(board_center[0]), float(board_center[1]), square_center_z)
    )
    surface_xform.AddScaleOp().Set(
        Gf.Vec3d(
            8.0 * CHESSBOARD_SQUARE_SIZE,
            8.0 * CHESSBOARD_SQUARE_SIZE,
            square_thickness,
        )
    )
    UsdGeom.Imageable(surface.GetPrim()).MakeInvisible()
    sim_utils.define_collision_properties(str(surface_path), SCENE_COLLISION_PROPERTIES)


@sim_utils.clone
def spawn_scene_usd(
    prim_path: str,
    cfg: UsdFileCfg,
    translation: tuple[float, float, float] | None = None,
    orientation: tuple[float, float, float, float] | None = None,
    **kwargs,
):
    """Spawn the resized scene and replace invalid collider materials."""
    prim = sim_utils.spawn_from_usd(
        prim_path,
        cfg,
        translation=translation,
        orientation=orientation,
        **kwargs,
    )
    _resize_chessboard(prim)
    material_path = f"{prim_path}/physicsMaterial"
    SCENE_PHYSICS_MATERIAL.func(material_path, SCENE_PHYSICS_MATERIAL)
    sim_utils.bind_physics_material(prim_path, material_path)
    return prim


@sim_utils.clone
def _spawn_rigid_usd(
    prim_path: str,
    cfg: UsdFileCfg,
    translation: tuple[float, float, float] | None = None,
    orientation: tuple[float, float, float, float] | None = None,
    **kwargs,
):
    """Spawn a rigid piece while preserving its authored collision hierarchy."""
    rigid_props = cfg.rigid_props or sim_utils.RigidBodyPropertiesCfg()
    mass_props = cfg.mass_props or sim_utils.MassPropertiesCfg(mass=PIECE_MASS_KG)

    # spawn_from_usd can modify existing nested colliders, but cannot add a
    # missing rigid body or mass API.
    cfg.rigid_props = None
    cfg.mass_props = None
    try:
        prim = sim_utils.spawn_from_usd(
            prim_path,
            cfg,
            translation=translation,
            orientation=orientation,
            **kwargs,
        )
    finally:
        cfg.rigid_props = rigid_props
        cfg.mass_props = mass_props

    sim_utils.define_rigid_body_properties(prim_path, rigid_props)
    sim_utils.define_mass_properties(prim_path, mass_props)
    # Keep one collision hierarchy per piece and force its authored collision
    # meshes through PhysX convex decomposition. The former compound of 4--6
    # overlapping primitives created one persistent contact pair per primitive
    # against the gripper SDF and reduced throughput to roughly 2 FPS.
    for child in Usd.PrimRange(prim):
        if not child.HasAPI(UsdPhysics.CollisionAPI):
            continue
        approximation = child.GetAttribute("physics:approximation")
        if approximation.IsValid():
            approximation.Set("convexDecomposition")

    # Speculative CCD catches fast contacts without the extra substeps of
    # sweep-based CCD.  Velocity and impulse caps below remain the backstop.
    physx_body = PhysxSchema.PhysxRigidBodyAPI.Apply(prim)
    physx_body.CreateEnableSpeculativeCCDAttr().Set(True)
    material_path = f"{prim_path}/physicsMaterial"
    PIECE_PHYSICS_MATERIAL.func(material_path, PIECE_PHYSICS_MATERIAL)
    sim_utils.bind_physics_material(prim_path, material_path)
    return prim


