def _chess_piece_spawn_cfg(usd_path: str) -> UsdFileCfg:
    """Build the common, contact-stable spawn config for a chess piece."""
    return UsdFileCfg(
        func=_spawn_rigid_usd,
        usd_path=usd_path,
        scale=(0.0008, 0.0008, 0.0008),
        rigid_props=PIECE_RIGID_PROPERTIES,
        mass_props=sim_utils.MassPropertiesCfg(mass=PIECE_MASS_KG),
        collision_props=PIECE_COLLISION_PROPERTIES,
    )


# Keep this task's contact tuning local.  The imported robot configuration is
# shared by other SO-101 tasks and should not be weakened globally.
SO101_CHESS_ROBOT_CFG = LEROBOT_SO101_SPAWN_CFG.copy()
