SO101_CHESS_ROBOT_CFG.spawn.collision_props.rest_offset = 0.0
# Keep the imported velocity limit and position-drive gains, but give this
# task's gripper more authority to retain the convex-decomposed pieces.
SO101_CHESS_ROBOT_CFG.actuators["gripper"].effort_limit_sim = GRIPPER_EFFORT_LIMIT


def attach_cameras(scene_cfg) -> None:
    """Attach cameras to a So101Chess scene cfg.

    Kept as a module-level helper so the teleop launcher can re-attach the
    cameras after IsaacLab's XR pipeline strips CameraCfg attributes via
    ``remove_camera_configs``. Called from ``__post_init__`` for normal runs.
    """
    scene_cfg.top_camera = CameraCfg(
        prim_path="{ENV_REGEX_NS}/top_camera",
        update_period=0.0,
        height=480,
        width=640,
        data_types=["rgb"],
        spawn=sim_utils.PinholeCameraCfg(
            focal_length=12.0,
            focus_distance=400.0,
            horizontal_aperture=20.955,
            clipping_range=(0.05, 10.0),
        ),
        offset=CameraCfg.OffsetCfg(
            pos=(-0.2294,-0.05, 1.20),
            rot=(0.6743, 0.212,-0.212 ,-0.6743),
            convention="opengl",
        ),
    )
    scene_cfg.right_wrist_camera = CameraCfg(
        prim_path="{ENV_REGEX_NS}/Scene/arm/gripper_link/right_wrist_camera",
        update_period=0.0,
        height=480,
        width=640,
        data_types=["rgb"],
        spawn=None,
    )

