@configclass
class So101ChessActionsCfg:
    """Pink IK pose and gripper action for So101Chess."""

    arm_action = PinkInverseKinematicsActionCfg(
        class_type=So101PinkInverseKinematicsAction,
        asset_name="robot",
        pink_controlled_joint_names=[
            "shoulder_pan",
            "shoulder_lift",
            "elbow_flex",
            "wrist_flex",
            "wrist_roll",
        ],
        hand_joint_names=["gripper"],
        target_eef_link_names={"chess": "gripper_frame_link"},
        controller=PinkIKControllerCfg(
            urdf_path=SO101_URDF_PATH,
            mesh_path=None,
            num_hand_joints=1,
            variable_input_tasks=[
                # The five-DoF arm cannot satisfy an arbitrary 6D pose.
                # Prioritize Cartesian position while retaining orientation as
                # a soft objective and damping singular configurations.
                FrameTask(
                    "gripper_frame_link",
                    position_cost=10.0,
                    orientation_cost=0.1,
                    lm_damping=0.01,
                    gain=1.0,
                ),
                DampingTask(cost=0.01),
            ],
            fixed_input_tasks=[],
            articulation_name="robot",
            base_link_name="base_link",
            show_ik_warnings=True,
            fail_on_joint_limit_violation=False,
        ),
        enable_gravity_compensation=False,
    )


@configclass
class So101ChessLeaderActionsCfg:
    """Ordered joint targets produced by a physical LeRobot SO-101 leader."""

    # These are absolute joint targets.  In particular, use_default_offset
    # must stay False: enabling it would add DATASET_INITIAL_JOINT_POS to every
    # leader reading instead of making the follower match the leader.
    arm_action = mdp.SlewRateLimitedJointPositionActionCfg(
        asset_name="robot",
        joint_names=["shoulder_pan", "shoulder_lift", "elbow_flex", "wrist_flex", "wrist_roll"],
        scale=1.0,
        offset={"wrist_roll": WRIST_ROLL_LEADER_OFFSET},
        use_default_offset=False,
        preserve_order=True,
        max_velocity=2.0,
        block_downward_near_board=True,
        eef_body_name="gripper_frame_link",
        gripper_joint_name="gripper",
        gripper_closed_threshold=GRIPPER_CLOSED_THRESHOLD,
        board_contact_clearance=0.002,
    )

    gripper_action = mdp.JointPositionActionCfg(
        asset_name="robot",
        joint_names=["gripper"],
        scale=1.0,
        offset=0.0,
        clip={"gripper": (GRIPPER_CLOSE_TARGET, GRIPPER_OPEN_LIMIT)},
        use_default_offset=False,
        preserve_order=True,
    )

