# =====================================================================
# 5) FINAL CONFIG
# =====================================================================
@configclass
class So101ChessTaskCfg(BaseILEnvCfg):

    scene: So101ChessSceneCfg = So101ChessSceneCfg(
        num_envs=1, env_spacing=2.5, replicate_physics=True
    )
    observations: So101ChessObservationsCfg = So101ChessObservationsCfg()
    actions: So101ChessActionsCfg = So101ChessActionsCfg()
    events: So101ChessEventCfg = So101ChessEventCfg()
    terminations: So101ChessTerminationsCfg = So101ChessTerminationsCfg()

    # Used by LeIsaac's teleoperation loop when resetting the physical leader.
    dynamic_reset_gripper_effort_limit: bool = False
    # Pinocchio must be imported before Isaac Sim when the default Pink action
    # configuration is used.
    requires_pinocchio: bool = True

    def use_teleop_device(self, teleop_device: str) -> None:
        """Select the six-joint action layout required by the SO-101 leader."""
        if teleop_device != "so101leader":
            raise ValueError(
                "So101Chess is configured for LeIsaac's 'so101leader' physical controller."
            )
        self.task_type = teleop_device
        self.actions = So101ChessLeaderActionsCfg()

    def preprocess_device_action(self, action: dict[str, Any], teleop_device) -> Any:
        """Map calibrated leader motor readings to ordered follower joint targets."""
        return preprocess_leisaac_device_action(action, teleop_device)

    def __post_init__(self):
        # EEF list — picked up by BaseILEnv methods and wired into the
        # recorder's entity_order by BaseILEnvCfg.__post_init__. Set before
        # super() so the base post-init sees it.
        self.eef_names = ["chess"]

        # Per-EEF action tensor layout — read by BaseILEnv to slice the action
        # tensor consumed by the Pink controller back into per-arm poses.
        self.eef_action_slices = {
            "chess": {"pos": (0, 3), "quat": (3, 7)},
        }

        # Contiguous gripper index ranges per EEF.
        self.eef_gripper_slices = {
            "chess": (7, 8),
        }

        super().__post_init__()

        # Sim defaults from the task YAML (override BaseILEnvCfg defaults).
        self.decimation = 4
        self.episode_length_s = 300.0
        self.sim.dt = 1/240.0
        self.sim.render_interval = 4
        # A driven articulation must solve contact after its joint drives;
        # otherwise the stiff gripper drive can overwrite the contact impulse
        # and advance a jaw through a small dynamic object in the same step.
        self.sim.physx.solve_articulation_contact_last = True
        # Applying external forces on every TGS iteration multiplies the
        # contact-solve cost and is unnecessary for this position-driven arm.
        self.sim.physx.enable_external_forces_every_iteration = False
        # The original scene briefly required about 76 MB during contact-rich
        # startup. Keep headroom above that even though the collider overrides
        # above eliminate the pathological broad contact envelope.
        self.sim.physx.gpu_collision_stack_size = 2**27

        # Cameras — attached to robot links. Under XR teleop, IsaacLab's
        # `remove_camera_configs` strips these before scene build; the
        # `xr_camera_reattach` hook lets the teleop script put them back
        # before `gym.make` runs.
        attach_cameras(self.scene)
